// VAR_IN_OUT structures and arrays modify caller storage directly
VAR_IN_OUT
    recipe : ST_Recipe;
    records : ARRAY[1..10] OF INT;
END_VAR
recipe.status := 1;
records[1] := records[1] + 1;
// Note: VAR_IN_OUT parameters cannot specify default initializers

// Variable-length array ARRAY[*] OF <type> with LOWER_BOUND/UPPER_BOUND
VAR_IN_OUT
    arr : ARRAY[*] OF INT;
END_VAR
VAR
    lb, ub, i : DINT;
END_VAR
lb := LOWER_BOUND(arr, 1);
ub := UPPER_BOUND(arr, 1);
FOR i := lb TO ub DO
    arr[i] := arr[i] + 1;
END_FOR;

// Standard IEC TON timer: MUST invoke unconditionally OUTSIDE CASE/IF every scan!
VAR
    timer : TON;
    runTimer : BOOL;
END_VAR
// Control via boolean IN flag (never put timer(...) only inside an IF/CASE arm):
runTimer := (state = 1) AND NOT resetCmd;
timer(IN := runTimer, PT := T#2s);
IF timer.Q THEN
    // Timer expired; timer.ET holds elapsed time
END_IF;

// 4-Stage Scan Order: 1) Edge sample 2) Reset/priority & CASE state transition
// 3) Unconditional top-level TON/R_TRIG calls 4) Unified output assignments
VAR
    state : INT := 0; // 0=IDLE, 1=RUN, 2=FAULT
END_VAR
IF emergencyStop THEN state := 2; END_IF;
CASE state OF
    0: IF startCmd AND NOT fault THEN state := 1; END_IF;
    1: IF faultCmd THEN state := 2; ELSIF stopCmd THEN state := 0; END_IF;
    2: IF resetCmd THEN state := 0; END_IF;
    ELSE state := 0;
END_CASE;
outActive := (state = 1); // Assign outputs unconditionally from current state
